        "■押さない：近S（+1）ガード後は押さない（5H 11FでCOUNTER）→投げ抜け（4D/6D）を仕込んでガード。ガンマブレード（236H +9）はガード→FDで離す。中距離で止まったらジャンプ→空振りに近S。",
