      "core": "チップは最速のダッシュと空ダ、壁走り、アルファブレード（236P）、幻朧斬（63214S）の投げで一瞬で表裏・上下の択を押し付けるが、体力が最も低いキャラ。こちらの狙いは慌てずガードで択を1〜2回受け、ガード後の確反とジャンプを落とした時の対空から一気にダメージを取ること。",
