        "開幕ダッシュ投げをするチップには、開幕にしゃがみガードしながら投げ抜けを仕込む。開幕2Kを出すチップには開幕しゃがみガード→ガード後に近S/2Kで触り返す。",
        "開幕バクステや後ろジャンプで逃げるチップには無理に追わず、中距離で6Pと2Hを構えてチップの飛び込みを待つ。チップは体力が低いので、1回の対空が勝ちに直結する。"
