        "中距離：ポチョムキンの遠S・5H・2S・6Hは長いが発生が遅い。ポチョムキンが技を振る間合いには入らず、ギリギリ届かない距離で待って、空振りに差し返す。特に遠Sと5Hの空振りは硬直が長い。ただしポチョバスが届く距離（密着〜1キャラ程度）には絶対に入らない。",
        "ポチョバス（632146P）の間合い管理：ポチョムキンの投げ間合いは広く、空キャンセルで更に伸びるかは要トレモ確認。中距離でダッシュして止まる行動は、ポチョバスの間合いに入って止まるのと同じ。接近するなら「ダッシュ→技を出す」か「ジャンプ」で、ダッシュして止まらない。",
        "メガフィスト（236P、前方に飛ぶ中段）はこちらの下段技を飛び越えて上から殴ってくる。ガード後は −6 なので2P/5Pなど5F技でのみ確反（近S/2Kは間に合わない）。地上で待っている時はしゃがみガードではなく、立ちガードを混ぜる。6Pで迎撃できるかは要トレモ確認。",
        "ポチョムキンの6Pは判定が強く、こちらの飛び込みをほぼ全て落とす。空中からの接近は、ハンマーフォールやスライドヘッドの硬直に合わせる。空ダは6Pで落とされるので、ジャンプからの着地は空ダよりFDで安全に着地する。",
        "ヒートナックル（623H）は空中ガードできない対空技。ポチョムキンの頭上に飛び込むと落とされる。飛び込みはポチョムキンの真上を避け、斜め前から。",
