        "メガフィスト（236P前方／214P後方）：前方に飛ぶ中段。下段技を飛び越える。前方版はガード後 −6、後方版は +1。→ 立ちガード→前方版は2P/5Pなど5F技でのみ確反（近S/2Kは間に合わない）。後方版は反撃不可。6Pで迎撃できるかは要トレモ確認。",
        "スライドヘッド（236S）：地面を叩き、地上のこちらを転ばせる。ガードしても +10 のガードクラッシュで相手有利（下段）。→ 発生を見たらジャンプ。ジャンプで避けたら着地に近S/2K始動で確反。",
        "ヒートナックル（623H）：空中ガード不能の対空技（地上ではガード可だが +3〜+10 で相手有利）。→ ポチョムキンの真上に飛ばない。空振りに近S/2K始動で確反。",
        "F.D.B.（214K）：飛び道具を反射する技。当たると吹き飛ばされる。→ 中距離で飛び道具を連打しない。ガードしたら −12 なので近S/2K始動で確反（距離次第、要トレモ確認）。",
        "ガルダインパクト（214H）：発生の遅い技（中段ではなくしゃがみガード可）。ガードさせると +19 のガードクラッシュで相手が大幅有利。→ ジャンプかバクステで避ける。ガード後は反撃せずFDで距離を取る。",
        "ヘブンリーポチョムキンバスター（632146S）：空中の相手を掴む覚醒必殺技。発生が早い。→ ゲージ50%以上のポチョムキンの前で飛ばない。空振りに最大確反。",
        "Giganter Kai（632146H）：バリアを出す覚醒必殺技（ガードさせるとポチョムキン側が大幅有利。挙動の詳細は要トレモ確認）。→ ガードした後は暴れず、次のポチョバスに備えてジャンプかバクステを混ぜる。",
