      "core": "ファウストは画面の半分以上に届く遠S・5H・2S・突きます（41236K）と、何が出るかな（236P）のアイテムで画面をランダムに制圧し、相手のミスにコンボを入れるキャラ。こちらの狙いはアイテムに惑わされず、ファウストの長い技の硬直と、スケアクロウ（214P/K/S）の着地に確反を入れて、ファウストが苦手な近距離を維持すること。",
