        "中距離：闇慈の遠S（扇で横に長い、発生速め）、5H（大きく振る、発生遅め）、6H（長いリーチの斬り、発生12F。Wikiでは16F、要トレモ確認）が主力。遠Sは6Pで潰せる。5H（発生15F）は置き6Pで潰せることがあるが、6Hは見てから潰すのは難しい（要トレモ確認）。",
