        "相手を壁に追い込んだ時：シンの切り返しはホークベイカー。壁際では近Sの後に一拍ガードを入れてホークベイカーを誘い、ガードして最大コンボで壁割り。相手がテンション50%以上の時はR.T.Lも警戒して一拍ガードを長めに。",
        "ゲージ・体力状況：相手のカロリーが満タンの時は追加が多く、固めが長い。カロリーが切れている瞬間が勝負なので、こちらの体力が少ない時はカロリーが切れるまでガードを固めてから一気に確反と起き攻めへ。こちらの体力が多い時は遠Sの間合いの外から差し返しに専念。"
