      "core": "遠S・5Hとミストファイナー（214[P/K/S]で構え→ボタンを離して発射。P＝上方向、K＝横、S＝下段）の長いリーチで中距離を支配し、ディール（236P/K/S）で貼ったカードをミストファイナーで撃ち抜く『ターンアップ』（ガードさせても+24のガードクラッシュ。カードが絡む条件の細部は要トレモ確認）で一気に壁割りまで持っていくキャラ。こちらの狙いは『遠Sの先端距離で技を振らない』『カードを貼られた状態でリスクを取らない』『ミストファイナーは3種ともガード後 −15 なので、届く距離でガードしたら必ず確反を取る（先端は届かないことが多い）』の3点。",
