      "core": "5H（10F）・遠S（12F）の剣と銃（ストリーク 236H、派生5H）で中距離を取り、ペネトレイト（236K）とトップアタック（214K）で崩しに来る。剣を先端で受けたら前ダッシュで番を取り、236K（−17）・623S（−70）・j.236H（−18）のガード後に近S始動で壁まで運ぶ。",
